WITH exploded AS (SELECT t.id, t.customer_id, pos + 1 AS item_no, line.product_id, line.price FROM carts t LATERAL VIEW POSEXPLODE(t.items) x AS pos, line) SELECT CASE WHEN product_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS product_id_tier, CASE WHEN item_no >= 3 THEN 'LARGE' ELSE 'SMALL' END AS item_no_tier, APPROX_PERCENTILE(item_no, 0.95) AS item_no_p95, ROUND(AVG(item_no), 2) AS avg_item_no, COUNT(*) AS event_count, MIN(price) AS min_price, APPROX_PERCENTILE(item_no, 0.5) AS item_no_p50, ROUND(AVG(item_no), 2) AS avg_item_no_2 FROM exploded GROUP BY CUBE (CASE WHEN product_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN item_no >= 3 THEN 'LARGE' ELSE 'SMALL' END);
